CREATE TABLE "ServicePreset" ("id" TEXT PRIMARY KEY, "nameAr" TEXT NOT NULL, "nameEn" TEXT NOT NULL, "category" TEXT NOT NULL, "kind" TEXT NOT NULL CHECK ("kind" IN ('SERVICE','FACILITY')), "active" BOOLEAN NOT NULL DEFAULT true, "version" INTEGER NOT NULL DEFAULT 0);
ALTER TABLE "Branch" ADD COLUMN "facilityIds" TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE "BranchService" ADD COLUMN "presetId" TEXT REFERENCES "ServicePreset"("id"), ADD COLUMN "openMinute" INTEGER, ADD COLUMN "closeMinute" INTEGER;
ALTER TABLE "BranchService" ADD CONSTRAINT "BranchService_hours_check" CHECK (("openMinute" IS NULL AND "closeMinute" IS NULL) OR ("openMinute" IS NOT NULL AND "closeMinute" IS NOT NULL AND "openMinute" BETWEEN 0 AND 1439 AND "closeMinute" BETWEEN 0 AND 1439 AND "openMinute" <> "closeMinute"));
ALTER TABLE "ServicePriceRequest" ADD COLUMN "presetId" TEXT REFERENCES "ServicePreset"("id"), ADD COLUMN "openMinute" INTEGER, ADD COLUMN "closeMinute" INTEGER;
ALTER TABLE "ServicePriceRequest" ADD CONSTRAINT "ServicePriceRequest_hours_check" CHECK (("openMinute" IS NULL AND "closeMinute" IS NULL) OR ("openMinute" IS NOT NULL AND "closeMinute" IS NOT NULL AND "openMinute" BETWEEN 0 AND 1439 AND "closeMinute" BETWEEN 0 AND 1439 AND "openMinute" <> "closeMinute"));
